import type { ComponentProps } from "react";

import { cn } from "../lib/cn";

/** Props of {@link CarouselCaption}. The attributes of a `div` plus the ones below. */
export type CarouselCaptionProps = ComponentProps<"div"> & {
  /**
   * Where the bar sits on the slide: "bottom" or "top".
   * @default "bottom"
   */
  position?: "bottom" | "top";
};

/**
 * A caption bar for a slide that is an image. It sits over the slide's edge on a fixed dark scrim with light text, so
 * the words keep at least 4.5:1 whatever the picture is (bright, busy, any theme). Put it inside a slide that is
 * `relative`; the slide is the positioning parent. The text is inset 4rem from both edges, so the overlay arrows
 * (`arrows="overlay"`) never sit on it.
 *
 * - `children` is the caption text.
 * - `position` is `"bottom"` or `"top"`.
 * - `className` goes on the bar.
 *
 * Keyboard: Not interactive; it takes no focus.
 * Accessibility: Plain text inside the slide's group, so it is read with the slide. The scrim and text colours are the
 * `--sheen-image-scrim` and `--sheen-on-image` tokens, which are the same in light and dark because a photo does not change with the theme; contrast is at least 9:1 over pure white. In forced
 * colors it becomes a Canvas bar with CanvasText.
 * Motion: None; it moves with the slide.
 *
 * @example
 * ```tsx
 * import { Carousel, CarouselCaption } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <Carousel aria-label="Landscapes">
 *       <div className="relative aspect-video bg-gradient-to-br from-lime-300 to-emerald-700">
 *         <CarouselCaption>Forest</CarouselCaption>
 *       </div>
 *     </Carousel>
 *   );
 * }
 * ```
 *
 * @see /components/carousel
 */
export function CarouselCaption({ position = "bottom", className, ...rest }: CarouselCaptionProps) {
  return (
    <div
      data-slot="carousel-caption"
      {...rest}
      className={cn(
        "absolute inset-x-0 py-3 ps-16 pe-16 text-base font-semibold text-(--sheen-on-image) forced-colors:bg-[Canvas] forced-colors:text-[CanvasText]",
        position === "top"
          ? "top-0 bg-linear-to-b from-(--sheen-image-scrim) from-75% to-transparent pb-6"
          : "bottom-0 bg-linear-to-t from-(--sheen-image-scrim) from-75% to-transparent pt-6",
        className,
      )}
    />
  );
}

"use client";

import { useCoarsePointer } from "../hooks/use-media-query";
import {
  Children,
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type FocusEvent,
  type KeyboardEvent,
} from "react";
import { animate, motion, useDragControls, useMotionValue, type PanInfo } from "motion/react";

import { cn } from "../lib/cn";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { observeIntersection } from "../hooks/use-intersection";
import { useResolvedDirection } from "../hooks/use-direction";
import { Button } from "../button/button";
import { useMergedRef } from "../lib/form";

import {
  defaultCarouselLabels,
  type CarouselProps,
  FLING,
  clamp,
  mod,
  resolvePerView,
  computeLayout,
  snapX,
  nearestPos,
  slideOffset,
  visibleRange,
  currentSlide,
  toPublic,
  PauseIcon,
  PlayIcon,
} from "./parts/model";
import { ArrowButton, Dots } from "./parts/parts";

export { type CarouselLabels, defaultCarouselLabels, type CarouselProps } from "./parts/model";
/**
 * Swipeable slides with arrows, dots, autoplay and loop. Every child is one slide. Use it for
 * galleries, featured cards and onboarding steps; slides can be glass, because only the track's
 * transform is animated.
 *
 * Props: see {@link CarouselProps} (`label` required, `slidesPerView` 1 or breakpoints by the
 * carousel's own width, `gap` 16, `align`, `loop`, `slidesToScroll`, `autoplay`, `arrows`,
 * `dots`, `index` / `defaultIndex` / `onIndexChange`, `effect`, `labels`, `slideClassName`,
 * `viewportClassName`, `className`).
 *
 * Captions over image slides: use `CarouselCaption`, a bar on a fixed dark scrim that keeps its text at 4.5:1 over any image.
 *
 * Keyboard: Tab reaches the pause button, the dots and the arrows; on any of them Left / Right go to the previous / next slide and Home / End to the first / last (swapped in right-to-left pages). With no arrows and no dots the slide area itself takes focus and answers the same keys. Focusing a partly visible slide brings it into view.
 * Accessibility: Follows the WAI-ARIA carousel pattern: a `section` with `aria-roledescription="carousel"`, slides as groups named "3 of 8", a polite live region that announces what is in view after navigating (silent while autoplay runs), and fully off-screen slides are `inert`. Autoplay pauses on hover, drag, a hidden tab or off-screen, and stops for good when keyboard focus enters (press Play to resume).
 * Motion: Drag or swipe with momentum, rubber-banding at the ends without `loop`, one SheenUI spring for arrows, dots and autoplay. Reduced motion: dragging still follows the finger, every move snaps, and autoplay never starts by itself.
 *
 * @example
 * ```tsx
 * import { Carousel } from "@sheenui/theme";
 *
 * export function Featured() {
 *   return (
 *     <Carousel aria-label="Featured templates" slidesPerView={{ 0: 1.15, 640: 2, 1024: 3 }} loop>
 *       <div className="glass-1 p-6">One</div>
 *       <div className="glass-1 p-6">Two</div>
 *       <div className="glass-1 p-6">Three</div>
 *     </Carousel>
 *   );
 * }
 * ```
 *
 * @see /components/carousel
 */
export function Carousel({
  children,
  "aria-label": label,
  slidesPerView = 1,
  gap = 16,
  align = "start",
  loop = false,
  slidesToScroll = 1,
  autoplay = false,
  arrows = "bottom",
  dots = true,
  index: indexProp,
  defaultIndex = 0,
  onIndexChange,
  effect = "none",
  labels: labelsProp,
  slideClassName,
  viewportClassName,
  className,
  onKeyDown,
  ref,
  ...props
}: CarouselProps) {
  const labels = { ...defaultCarouselLabels, ...labelsProp };
  const slides = Children.toArray(children);
  const count = slides.length;
  const reduced = useSheenReducedMotion();
  const statusId = useId();

  // Elements are kept in state, so measuring starts whenever they mount: a carousel that first
  // renders with no slides (data still loading) and fills later is measured like a fresh one.
  const [viewport, setViewport] = useState<HTMLDivElement | null>(null);
  const [root, setRoot] = useState<HTMLElement | null>(null);
  const rootRef = useRef<HTMLElement | null>(null);
  const attachRoot = useMergedRef(rootRef, setRoot, ref);
  const slideRefs = useRef<(HTMLDivElement | null)[]>([]);
  const [width, setWidth] = useState(0);
  const rtl = useResolvedDirection(undefined, rootRef) === "rtl";
  const sign = rtl ? -1 : 1;

  const perView = resolvePerView(slidesPerView, width);
  const layout = useMemo(
    () => computeLayout(width, count, perView, gap, align, loop, slidesToScroll),
    [width, count, perView, gap, align, loop, slidesToScroll],
  );
  const layoutRef = useRef(layout);
  const signRef = useRef(sign);

  /** Physical translateX of the track. Logical position = x * sign. */
  const x = useMotionValue(0);
  const controlled = indexProp !== undefined;
  const [pos, setPos] = useState(indexProp ?? defaultIndex);
  const posRef = useRef(pos);
  const [announcement, setAnnouncement] = useState("");
  // Read inside the callbacks through refs, so they (and the effects that use them) stay stable.
  const latest = useRef({ reduced, labels, onIndexChange, controlled });
  // Refreshed after every commit, before the effects below run (effects run in order), and never during render.
  useLayoutEffect(() => {
    layoutRef.current = layout;
    signRef.current = sign;
    posRef.current = pos;
    latest.current = { reduced, labels, onIndexChange, controlled };
  });
  /** A move the user asked for while controlled: announced when the prop follows. */
  const pending = useRef<{ index: number; announce: boolean } | null>(null);

  const publicIndex = toPublic(layout, pos);
  const positions = layout.loop ? count : layout.snaps.length;
  const scrollable = layout.ready ? (layout.loop ? count > 1 : layout.snaps.length > 1) : count > 1;
  const canDrag = scrollable && layout.ready;
  // Asked to loop but too few slides to wrap seamlessly: the arrows rewind instead of stopping.
  const rewinds = loop && !layout.loop && positions > 1;
  const canPrev = layout.loop || rewinds || publicIndex > 0;
  const canNext = layout.loop || rewinds || publicIndex < positions - 1;

  /* ----- Measure (width) ----- */
  useLayoutEffect(() => {
    if (!viewport) return;
    const measure = () => setWidth(viewport.clientWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(viewport);
    return () => observer.disconnect();
  }, [viewport]);

  /* ----- Move the track (no onIndexChange: callers decide) ----- */
  const moveTo = useCallback(
    (target: number, options: { velocity?: number; instant?: boolean; announce?: boolean } = {}) => {
      const l = layoutRef.current;
      const p = l.loop ? target : clamp(target, 0, Math.max(0, l.snaps.length - 1));
      setPos(p);
      posRef.current = p;
      const to = snapX(l, p) * signRef.current;
      const { reduced: still, labels: words } = latest.current;
      if (still || options.instant || !l.ready) {
        x.stop();
        x.set(to);
      } else {
        // Physics spring (the numbers behind `spring.smooth`, no overshoot): time-defined springs
        // (`visualDuration`) ignore the release velocity and restart from rest, which reads as a dip.
        // Without an explicit velocity Motion carries on from the value's current velocity.
        const v = options.velocity;
        const distance = Math.abs(to - x.get());
        if (v !== undefined && Math.abs(v) > 500 && distance > 8) {
          // A throw leaves at the speed of the hand and only slows down: an ease-out whose opening slope (2) matches the
          // release speed (duration = 2 x distance / speed). A spring covering the rest of a slide accelerated to ~2x.
          animate(x, to, {
            duration: Math.min(0.7, Math.max(0.25, (2 * distance) / Math.abs(v))),
            ease: [0.25, 0.5, 0.4, 1],
          });
        } else {
          animate(x, to, { ...FLING, ...(v !== undefined && { velocity: v }) });
        }
      }
      if (options.announce !== false && l.ready) {
        const range = visibleRange(l, p);
        setAnnouncement(
          range && range[0] !== range[1]
            ? words.statusRange(range[0] + 1, range[1] + 1, l.count)
            : words.status((range ? range[0] : currentSlide(l, p)) + 1, l.count),
        );
      }
    },
    [x],
  );

  /* ----- A user or autoplay move: move (uncontrolled) or ask the owner (controlled) ----- */
  const go = useCallback(
    (next: number, options: { velocity?: number; announce?: boolean; settle?: boolean } = {}) => {
      const l = layoutRef.current;
      const target = l.loop ? next : clamp(next, 0, Math.max(0, l.snaps.length - 1));
      const from = toPublic(l, posRef.current);
      const to = toPublic(l, target);
      const { onIndexChange: notify, controlled: isControlled } = latest.current;
      if (isControlled) {
        // Only the prop moves a controlled carousel. A released drag springs back meanwhile;
        // if the owner accepts, the prop change redirects that spring to the new slide.
        if (options.settle) moveTo(posRef.current, { velocity: options.velocity, announce: false });
        if (to !== from) {
          pending.current = { index: to, announce: options.announce !== false };
          notify?.(to);
        }
        return;
      }
      moveTo(target, options);
      if (to !== from) notify?.(to);
    },
    [moveTo],
  );

  // Re-snap (instantly) when the geometry or direction changes: resize, slides per view, slide count.
  useLayoutEffect(() => {
    if (!layout.ready) return;
    const p = layout.loop ? posRef.current : clamp(posRef.current, 0, layout.snaps.length - 1);
    if (p !== posRef.current) {
      posRef.current = p;
      setPos(p);
    }
    x.stop();
    x.set(snapX(layout, p) * sign);
  }, [layout, sign, x]);

  // Controlled index: follow the prop (silent unless the user asked for this move).
  useEffect(() => {
    if (indexProp === undefined || !layout.ready) return;
    const current = toPublic(layout, posRef.current);
    const wanted = layout.loop ? mod(indexProp, count) : clamp(indexProp, 0, layout.snaps.length - 1);
    const asked = pending.current;
    pending.current = null;
    if (wanted === current) return;
    const announce = asked?.index === wanted && asked.announce;
    if (layout.loop) {
      let delta = mod(wanted - current, count);
      if (delta > count / 2) delta -= count;
      moveTo(posRef.current + delta, { announce });
    } else moveTo(wanted, { announce });
  }, [indexProp, layout, count, moveTo]);

  /* ----- Per-slide transforms: loop wrapping and the scale effect ----- */
  const transformsActive = layout.loop || effect === "scale";
  useEffect(() => {
    const els = slideRefs.current;
    if (!layout.ready || !transformsActive) {
      els.forEach((el) => el && (el.style.transform = ""));
      return;
    }
    const apply = (physical: number) => {
      const at = physical * sign;
      for (let i = 0; i < layout.count; i++) {
        const el = els[i];
        if (!el) continue;
        const natural = i * layout.stride + at;
        const shown = slideOffset(layout, i, at);
        let scale = 1;
        if (effect === "scale") {
          const distance = Math.abs(shown - layout.offset0) / (layout.stride || 1);
          scale = 1 - 0.08 * Math.min(1, distance);
        }
        const dx = (shown - natural) * sign;
        // Only slides that are actually displaced or scaled get a transform (no no-op writes per frame).
        const next =
          Math.abs(dx) < 0.01 && scale === 1
            ? ""
            : `translate3d(${dx}px,0,0)${scale !== 1 ? ` scale(${scale.toFixed(4)})` : ""}`;
        if (el.style.transform !== next) el.style.transform = next;
      }
    };
    apply(x.get());
    return x.on("change", apply);
  }, [layout, transformsActive, effect, sign, x]);

  /* ----- Which slides are on screen (the rest are inert) ----- */
  const target = layout.ready ? snapX(layout, pos) : 0;
  const current = currentSlide(layout, pos);
  const visibility = slides.map((_, i) => {
    if (!layout.ready) return i < Math.ceil(perView) ? "full" : "none";
    const p = slideOffset(layout, i, target);
    if (p >= -0.5 && p + layout.slideW <= layout.width + 0.5) return "full";
    if (p < layout.width - 0.5 && p + layout.slideW > 0.5) return "partial";
    return "none";
  });

  /** Keyboard focus landed in a slide that is only partly visible: bring it into view. */
  const revealSlide = (i: number) => {
    const l = layoutRef.current;
    if (!l.ready) return;
    if (l.loop) {
      let delta = mod(i - mod(posRef.current, l.count), l.count);
      if (delta > l.count / 2) delta -= l.count;
      go(posRef.current + delta);
    } else go(nearestPos(l, clamp(l.offset0 - i * l.stride, -l.maxScroll, 0)));
  };

  /* ----- Drag ----- */
  const dragStart = useRef(0);
  const dragged = useRef(false);
  // Motion's own drag listener forces `touch-action: pan-y`, which also blocks the browser's page pinch-zoom over
  // the track. We start the drag ourselves (dragListener off) so the track can say `pan-y pinch-zoom`.
  const dragControls = useDragControls();
  const [dragging, setDragging] = useState(false);

  const onDragStart = () => {
    dragStart.current = posRef.current;
    dragged.current = true;
    setDragging(true);
  };

  const onDragEnd = (_: unknown, info: PanInfo) => {
    setDragging(false);
    const l = layoutRef.current;
    const v = info.velocity.x * sign; // logical: negative = towards the next slides
    // Momentum: project with what the spring itself would coast (v / (omega * e) ~ 0.02 s of travel; 0.05 s
    // is generous), snap to the nearest position, and allow one slide per throw unless the throw is very fast.
    // A far projection made the track accelerate after release (the spring had to cover ~10x its own coast).
    let next = nearestPos(l, x.get() * sign + v * 0.05);
    const reach = Math.abs(v) > 4000 ? 3 : 1;
    next = Math.min(dragStart.current + reach, Math.max(dragStart.current - reach, next));
    if (next === dragStart.current && Math.abs(v) > 350) next += v < 0 ? 1 : -1;
    // A slow but deliberate drag (about a quarter of a slide, or 72px) also turns the page, as native swipers do.
    const travelled = snapX(l, dragStart.current) - x.get() * sign; // > 0: dragged towards the next slides
    if (next === dragStart.current && Math.abs(travelled) > Math.min(72, 0.25 * (l.stride || 1)))
      next += travelled > 0 ? 1 : -1;
    go(next, { velocity: info.velocity.x, settle: true });
  };

  /* ----- Autoplay ----- */
  const interval = typeof autoplay === "number" ? Math.max(1000, autoplay) : 5000;
  const [userPlaying, setUserPlaying] = useState<boolean | null>(null);
  const playing = Boolean(autoplay) && (userPlaying ?? !reduced);
  const [hovered, setHovered] = useState(false);
  const [hiddenTab, setHiddenTab] = useState(false);
  const [offscreen, setOffscreen] = useState(false);
  const running = playing && scrollable && layout.ready && !hovered && !dragging && !hiddenTab && !offscreen;
  const progress = useMotionValue(0);

  useEffect(() => {
    if (!autoplay || !root) return;
    const onVisibility = () => setHiddenTab(document.visibilityState === "hidden");
    document.addEventListener("visibilitychange", onVisibility);
    const stopObserving = observeIntersection(root, (entry) => setOffscreen(!entry.isIntersecting));
    return () => {
      document.removeEventListener("visibilitychange", onVisibility);
      stopObserving();
    };
  }, [autoplay, root]);

  // A new position restarts the countdown.
  useEffect(() => {
    progress.set(0);
  }, [pos, progress]);

  useEffect(() => {
    if (!running) return;
    const remaining = (1 - progress.get()) * interval;
    const controls = animate(progress, 1, {
      duration: remaining / 1000,
      ease: "linear",
      onComplete: () => {
        const l = layoutRef.current;
        const atEnd = !l.loop && posRef.current >= l.snaps.length - 1;
        // Rotation is silent: the live region is off while it plays.
        go(atEnd ? 0 : posRef.current + (l.loop ? l.step : 1), { announce: false });
      },
    });
    return () => controls.stop();
  }, [running, interval, progress, go, pos]);

  const onFocusCapture = (event: FocusEvent<HTMLElement>) => {
    // APG: keyboard focus entering the carousel stops rotation until Play is pressed.
    const from = event.relatedTarget;
    const entering = !from || !event.currentTarget.contains(from);
    if (entering && playing && event.target.matches(":focus-visible")) setUserPlaying(false);
  };

  /* ----- Navigation helpers ----- */
  const prev = () => {
    if (!canPrev) return;
    if (rewinds && posRef.current <= 0) go(positions - 1);
    else go(posRef.current - (layout.loop ? layout.step : 1));
  };
  const next = () => {
    if (!canNext) return;
    if (rewinds && posRef.current >= positions - 1) go(0);
    else go(posRef.current + (layout.loop ? layout.step : 1));
  };
  const goToDot = (d: number) => {
    if (layout.loop) {
      let delta = mod(d - mod(posRef.current, count), count);
      if (delta > count / 2) delta -= count;
      go(posRef.current + delta);
    } else go(d);
  };

  /** ←/→ (mirrored in RTL), Home and End: on the control row, the overlay arrows and a focusable viewport. */
  const onNavKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    const keys: Record<string, () => void> = {
      ArrowLeft: rtl ? next : prev,
      ArrowRight: rtl ? prev : next,
      Home: () => goToDot(0),
      End: () => goToDot(positions - 1),
    };
    const action = keys[event.key];
    if (!action || event.altKey || event.ctrlKey || event.metaKey) return;
    event.preventDefault();
    action();
    // Roving focus on the dots: keep focus on the active one.
    const dot = (event.target as HTMLElement).closest("[data-carousel-dot]");
    if (dot) {
      requestAnimationFrame(() => {
        rootRef.current?.querySelector<HTMLElement>("[data-carousel-dot][aria-current='true']")?.focus();
      });
    }
  };

  // Dots must fit: on touch screens each needs a 44px target, otherwise 24px.
  const coarse = useCoarsePointer();
  const dotSize = coarse ? 44 : 24;
  const reserved = (autoplay ? 52 : 0) + (arrows === "bottom" ? 2 * (coarse ? 48 : 44) + 16 : 0);
  const dotsFit = !layout.ready || positions * dotSize <= layout.width - reserved;
  const showControls = scrollable && (dots || arrows === "bottom" || autoplay);
  // No arrows and no dots to Tab to: the slide area itself takes focus and the arrow keys.
  const focusViewport = canDrag && arrows === false && !(dots && dotsFit);

  // Accessible names of the dots: the slide (or slides) each one shows.
  const dotLabels = Array.from({ length: positions }, (_, d) => {
    const range = layout.loop ? ([d, d] as const) : visibleRange(layout, d);
    if (range && range[0] !== range[1]) return labels.goToRange(range[0] + 1, range[1] + 1, count);
    return labels.goTo((range ? range[0] : layout.loop ? d : currentSlide(layout, d)) + 1, count);
  });

  if (count === 0) return null;

  return (
    // eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions -- APG carousel: the region only catches the keys (arrows, Home, End) and focus bubbling up from the controls and slides inside it
    <section
      ref={attachRoot}
      aria-roledescription={labels.carousel}
      aria-label={label}
      data-slot="carousel"
      className={cn("relative flex w-full min-w-0 flex-col gap-4", className)}
      onFocusCapture={onFocusCapture}
      onPointerEnter={(e) => e.pointerType === "mouse" && setHovered(true)}
      onPointerLeave={(e) => e.pointerType === "mouse" && setHovered(false)}
      onKeyDown={onKeyDown}
      {...props}
    >
      {showControls && (
        // First in the DOM (APG: the rotation control comes before the slides), shown below them.
        // eslint-disable-next-line jsx-a11y/no-static-element-interactions -- arrow keys pressed on the buttons and dots inside are handled here; the row is not a control itself
        <div className="order-last flex min-h-10 items-center gap-3" onKeyDown={onNavKeyDown}>
          {autoplay && (
            <Button
              variant="glass"
              size="icon"
              onClick={() => setUserPlaying(!playing)}
              aria-label={playing ? labels.pause : labels.play}
              className="size-9 shrink-0 rounded-sheen-full"
            >
              {playing ? <PauseIcon /> : <PlayIcon />}
            </Button>
          )}
          {dots &&
            (dotsFit ? (
              <Dots
                count={positions}
                active={publicIndex}
                onSelect={goToDot}
                progress={progress}
                showProgress={running && !reduced}
                coarse={coarse}
                reduced={reduced}
                rtl={rtl}
                names={dotLabels}
                label={labels.picker}
              />
            ) : (
              <span aria-hidden className="px-1 text-sm font-medium text-sheen-fg-muted tabular-nums">
                {labels.counter(publicIndex + 1, positions)}
              </span>
            ))}
          {arrows === "bottom" && (
            <div className="ms-auto flex shrink-0 gap-2">
              <ArrowButton side="prev" rtl={rtl} disabled={!canPrev} onClick={prev} label={labels.previous} />
              <ArrowButton side="next" rtl={rtl} disabled={!canNext} onClick={next} label={labels.next} />
            </div>
          )}
        </div>
      )}

      <div className="relative">
        {/* overflow-x: clip, not hidden: focus can't scroll it, and vertical shadows aren't cut. */}
        {/* eslint-disable-next-line jsx-a11y/no-static-element-interactions -- it becomes a focusable "group" (role, name and key handler) only when there is no other control to focus (`focusViewport`) */}
        <div
          ref={setViewport}
          role={focusViewport ? "group" : undefined}
          aria-label={focusViewport ? labels.viewport : undefined}
          aria-keyshortcuts={focusViewport ? "ArrowLeft ArrowRight Home End" : undefined}
          // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex -- only set together with the group role and its key handler above (`focusViewport`)
          tabIndex={focusViewport ? 0 : undefined}
          onKeyDown={focusViewport ? (e) => e.target === e.currentTarget && onNavKeyDown(e) : undefined}
          className={cn(
            "min-w-0 overflow-x-clip py-1 [overflow-clip-margin:4px]",
            focusViewport &&
              "rounded-sheen-lg focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
            viewportClassName,
          )}
          onDragStartCapture={(e) => e.preventDefault()}
          onPointerDownCapture={() => {
            dragged.current = false;
          }}
          onClickCapture={(e) => {
            // A drag that ends over a link or button must not also click it.
            if (dragged.current) {
              e.preventDefault();
              e.stopPropagation();
              dragged.current = false;
            }
          }}
        >
          <motion.div
            data-slot="carousel-track"
            drag={canDrag ? "x" : false}
            dragConstraints={
              layout.loop
                ? undefined
                : rtl
                  ? { left: -(layout.snaps[0] ?? 0), right: -(layout.snaps[layout.snaps.length - 1] ?? 0) }
                  : { left: layout.snaps[layout.snaps.length - 1] ?? 0, right: layout.snaps[0] ?? 0 }
            }
            dragElastic={0.18}
            dragMomentum={false}
            dragListener={false}
            dragControls={dragControls}
            onPointerDown={(event) => {
              if (canDrag && event.button === 0) dragControls.start(event, { snapToCursor: false });
            }}
            dragDirectionLock
            onDragStart={onDragStart}
            onDragEnd={onDragEnd}
            style={{ x, gap, touchAction: "pan-y pinch-zoom", WebkitTouchCallout: "none" }}
            className={cn(
              "flex select-none [&_img]:[-webkit-user-drag:none]",
              canDrag && "cursor-grab active:cursor-grabbing",
            )}
          >
            {slides.map((slide, i) => (
              // eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions -- onFocus only reveals a partly visible slide when keyboard focus lands inside it
              <div
                key={i}
                ref={(el) => {
                  slideRefs.current[i] = el;
                }}
                role="group"
                aria-roledescription={labels.slide}
                aria-label={labels.slideLabel(i + 1, count)}
                inert={visibility[i] === "none"}
                data-visible={visibility[i]}
                data-current={i === current || undefined}
                onFocus={(e) => {
                  if (visibility[i] !== "full" && (e.target as HTMLElement).matches(":focus-visible")) revealSlide(i);
                }}
                style={{
                  flex: `0 0 calc((100% - ${perView - 1} * ${gap}px) / ${perView})`,
                }}
                className={cn("min-w-0 origin-center", slideClassName)}
              >
                {slide}
              </div>
            ))}
          </motion.div>
        </div>

        {arrows === "overlay" && scrollable && (
          <>
            <ArrowButton
              side="prev"
              overlay
              rtl={rtl}
              disabled={!canPrev}
              onClick={prev}
              onKeyDown={onNavKeyDown}
              label={labels.previous}
            />
            <ArrowButton
              side="next"
              overlay
              rtl={rtl}
              disabled={!canNext}
              onClick={next}
              onKeyDown={onNavKeyDown}
              label={labels.next}
            />
          </>
        )}
      </div>

      {/* Polite while you navigate; off while it rotates on its own (APG). */}
      <div id={statusId} aria-live={running ? "off" : "polite"} aria-atomic="true" className="sr-only">
        {announcement}
      </div>
    </section>
  );
}

import { type ComponentProps, type ReactNode } from "react";

import { cn } from "../../lib/cn";
import { clamp } from "../../lib/math";

/** The physics behind `spring.smooth`: used for moves that must inherit the release velocity. */
export const FLING = { type: "spring", stiffness: 305, damping: 34.9, mass: 1 } as const;

/**
 * Carousel: swipeable slides with arrows, dots, autoplay and loop.
 *
 *   <Carousel aria-label="Featured templates" slidesPerView={{ 0: 1.15, 640: 2, 1024: 3 }} loop>
 *     <TemplateCard … />
 *     <TemplateCard … />
 *   </Carousel>
 *
 * Every child is one slide. Accessibility follows the WAI-ARIA APG carousel pattern:
 * a <section> with aria-roledescription="carousel", slides as role="group" +
 * aria-roledescription="slide" ("3 of 8"), a polite live region that announces what is in
 * view when you navigate ("Slide 3 of 8", or "Slides 4 to 6 of 8" when several fit), silent
 * while it rotates on its own, and slides that are fully off screen are `inert` (not
 * focusable, not read). Focusing a slide that is only partly in view brings it into view.
 *
 * Keyboard: Tab reaches the pause button, the dots and the arrows (bottom or overlay). On
 * any of them, ←/→ go to the previous / next slide and Home / End to the first / last.
 * With arrows={false} and no dots, the slide area itself takes focus and answers the same keys.
 *
 * Motion: drag or swipe the track (Motion drag): release projects your velocity forward
 * (momentum) and springs to the nearest slide, so a hard flick travels several slides.
 * Without loop the ends rubber-band. With loop, slides wrap around individually (no
 * cloned DOM), so it is endless in both directions. Arrows, dots and autoplay use the
 * same spring. Reduced motion: dragging still follows your finger (direct manipulation),
 * but every move snaps instantly, and autoplay does not start on its own.
 *
 * Autoplay pauses while the pointer is over the carousel, while it is being dragged,
 * while the tab is hidden or the carousel is off screen, and stops for good when keyboard
 * focus enters it (press Play to resume). The active dot fills up as the next slide nears.
 *
 * Direction: follows the page. In a right-to-left page the first slide sits on the right,
 * "next" moves leftwards, the arrows and the dot pill mirror, and ←/→ swap meaning.
 *
 * Controlled: pass `index` and update it from `onIndexChange`; the carousel only moves
 * when the prop changes (a drag that isn't accepted springs back). onIndexChange fires for
 * user and autoplay moves, never on mount or when following the prop.
 *
 * Only transform is animated. Slides may be glass: nothing fades or masks their wrappers.
 */

/* ---------- Labels ---------- */

/** Every UI string of {@link Carousel}; pass a partial through its `labels` prop to translate it. */
export type CarouselLabels = {
  /** aria-roledescription of the whole carousel. */
  carousel: string;
  /** aria-roledescription of each slide. */
  slide: string;
  /** Accessible name of a slide: (position, total) → "3 of 8". */
  slideLabel: (position: number, total: number) => string;
  /** Accessible name of the previous arrow. */
  previous: string;
  /** Accessible name of the next arrow. */
  next: string;
  /** Accessible name of a dot that shows one slide: (slide, total) → "Slide 3". */
  goTo: (position: number, total: number) => string;
  /** Accessible name of a dot that shows several slides: (first, last, total) → "Slides 4 to 6". */
  goToRange: (first: number, last: number, total: number) => string;
  /** Accessible name of the dot group. */
  picker: string;
  /** Play button (autoplay is stopped). */
  play: string;
  /** Pause button (autoplay is running). */
  pause: string;
  /** Live announcement after navigating to one slide: (slide, total) → "Slide 3 of 8". */
  status: (position: number, total: number) => string;
  /** Live announcement when several slides are in view: (first, last, total) → "Slides 4 to 6 of 8". */
  statusRange: (first: number, last: number, total: number) => string;
  /** Compact visible counter used when the dots don't fit: (position, total) → "3 / 12". */
  counter: (position: number, total: number) => string;
  /** Accessible name of the slide area when it takes keyboard focus itself (no arrows, no dots). */
  viewport: string;
};

/** The English strings of {@link Carousel}. Spread it to build your own set. */
export const defaultCarouselLabels: CarouselLabels = {
  carousel: "carousel",
  slide: "slide",
  slideLabel: (i, n) => `${i} of ${n}`,
  previous: "Previous slide",
  next: "Next slide",
  goTo: (i) => `Slide ${i}`,
  goToRange: (a, b) => `Slides ${a} to ${b}`,
  picker: "Choose a slide",
  play: "Start automatic slide show",
  pause: "Pause automatic slide show",
  status: (i, n) => `Slide ${i} of ${n}`,
  statusRange: (a, b, n) => `Slides ${a} to ${b} of ${n}`,
  counter: (i, n) => `${i} / ${n}`,
  viewport: "Slides",
};

/* ---------- Props ---------- */

/** Props of {@link Carousel}. The attributes of a `section` (minus `aria-label`) and the ones below. */
export type CarouselProps = Omit<ComponentProps<"section">, "children" | "aria-label"> & {
  /** Each child becomes one slide of the carousel. */
  children?: ReactNode;
  /** Accessible name of the carousel, e.g. "Featured products". Required. */
  "aria-label": string;
  /**
   * Slides visible at once. A number, or breakpoints keyed by the carousel's own width in px
   * (container width, not the window): { 0: 1.15, 640: 2, 1024: 3 }. Fractions show a peek
   * of the next slide.
   */
  slidesPerView?: number | Record<number, number>;
  /**
   * Sets the space left between slides, in px.
   * @default 16
   */
  gap?: number;
  /**
   * Where the current slide sits: at the start, or centred (great with a fractional view + loop).
   * @default "start"
   */
  align?: "start" | "center";
  /**
   * Endless in both directions. Needs enough slides to fill the view plus one; otherwise it rewinds.
   * @default false
   */
  loop?: boolean;
  /**
   * How far the arrows move: a number of slides, or "page" (the slides in view).
   * @default 1
   */
  slidesToScroll?: number | "page";
  /**
   * Advance on its own: true (every 5 s) or an interval in ms. Never starts by itself under reduced motion.
   * @default false
   */
  autoplay?: boolean | number;
  /**
   * "bottom": in the control row. "overlay": floating on the slides' edges. false: none.
   * @default "bottom"
   */
  arrows?: "bottom" | "overlay" | false;
  /**
   * Show the dots (a "3 / 12" counter replaces them when they don't fit).
   * @default true
   */
  dots?: boolean;
  /** Controlled position (snap index; with loop, the slide index). Update it from onIndexChange. */
  index?: number;
  /**
   * Sets the starting position when uncontrolled.
   * @default 0
   */
  defaultIndex?: number;
  /** A user or autoplay move asks for a new position (never fired on mount or when following `index`). */
  onIndexChange?: (index: number) => void;
  /**
   * "scale": slides away from the current one shrink a little (transform only).
   * @default "none"
   */
  effect?: "none" | "scale";
  /** Override any UI string (i18n). */
  labels?: Partial<CarouselLabels>;
  /** Adds extra classes to each slide wrapper. */
  slideClassName?: string;
  /** Adds extra classes to the clipping viewport. */
  viewportClassName?: string;
};

/* ---------- Geometry ---------- */

/*
 * All geometry is "logical": distances are measured from the start edge (left in LTR, right
 * in RTL) and a negative track position moves slides towards the start. The motion value
 * `x` is physical (translateX); `sign` (+1 LTR, -1 RTL) converts between the two.
 */
/** The computed geometry of the track: slide size, stride, offsets and snap positions. @internal */
export type Layout = {
  ready: boolean;
  width: number;
  perView: number;
  slideW: number;
  stride: number;
  count: number;
  offset0: number;
  maxScroll: number;
  loop: boolean;
  /** Loop: slides are wrapped into [lo, lo + total). */
  lo: number;
  total: number;
  /** Non-loop: x of each snap point. */
  snaps: number[];
  /** Positions the arrows move by. */
  step: number;
};

/** Re-exports the shared `clamp` so the carousel parts import it from one place. @internal */
export { clamp };
/** A modulo that stays non-negative for negative values. @internal */
export const mod = (v: number, n: number) => ((v % n) + n) % n;
/** Wraps a value into the half-open range from `min` to `max`. @internal */
export const wrap = (min: number, max: number, v: number) => min + mod(v - min, max - min);

/** Resolves the slides-per-view spec to a number for a viewport width. @internal */
export function resolvePerView(spec: CarouselProps["slidesPerView"], width: number) {
  if (typeof spec === "number") return Math.max(1, spec);
  const entries = Object.entries(spec ?? { 0: 1 })
    .map(([k, v]) => [Number(k), v] as const)
    .sort((a, b) => a[0] - b[0]);
  let value = entries[0]?.[1] ?? 1;
  for (const [min, v] of entries) if (width >= min) value = v;
  return Math.max(1, value);
}

/** Computes slide width, stride, offsets and snap positions for the current size. @internal */
export function computeLayout(
  width: number,
  count: number,
  perView: number,
  gap: number,
  align: "start" | "center",
  wantLoop: boolean,
  slidesToScroll: number | "page",
): Layout {
  const slideW = width > 0 ? (width - gap * (perView - 1)) / perView : 0;
  const stride = slideW + gap;
  const total = count * stride;
  const offset0 = align === "center" ? (width - slideW) / 2 : 0;
  const maxScroll = Math.max(0, total - gap - width);
  const step = slidesToScroll === "page" ? Math.max(1, Math.floor(perView)) : Math.max(1, Math.round(slidesToScroll));
  // Endless only when every slide can sit off screen while the view is full: total >= view + one slide.
  const loop = wantLoop && count > 1 && width > 0 && total >= width + slideW + 1;
  const lo = (width - total - slideW) / 2;

  const snaps: number[] = [];
  if (!loop) {
    for (let i = 0; i < count; i += step) {
      const x = clamp(offset0 - i * stride, -maxScroll, 0);
      const last = snaps[snaps.length - 1];
      if (last === undefined || Math.abs(last - x) > 0.5) snaps.push(x);
    }
    if (snaps.length === 0) snaps.push(0);
    // Make sure the very end is reachable.
    if (Math.abs((snaps[snaps.length - 1] ?? 0) + maxScroll) > 0.5 && maxScroll > 0) snaps.push(-maxScroll);
  }
  return {
    ready: width > 0 && count > 0,
    width,
    perView,
    slideW,
    stride,
    count,
    offset0,
    maxScroll,
    loop,
    lo,
    total,
    snaps,
    step,
  };
}

/** The track offset of a snap position. @internal */
export function snapX(layout: Layout, pos: number) {
  if (layout.loop) return layout.offset0 - pos * layout.stride;
  return layout.snaps[clamp(pos, 0, layout.snaps.length - 1)] ?? 0;
}

/** The snap position nearest to a track offset. @internal */
export function nearestPos(layout: Layout, x: number) {
  if (layout.loop) return Math.round((layout.offset0 - x) / (layout.stride || 1));
  let best = 0;
  layout.snaps.forEach((s, i) => {
    if (Math.abs(s - x) < Math.abs((layout.snaps[best] ?? 0) - x)) best = i;
  });
  return best;
}

/** Where slide `i` sits in the viewport (px from its start edge) when the track is at `x`. */
export function slideOffset(layout: Layout, i: number, x: number) {
  const p = i * layout.stride + x;
  return layout.loop ? wrap(layout.lo, layout.lo + layout.total, p) : p;
}

/**
 * The slides fully in view at position `pos`, as [first, last] slide indices, when they are a
 * contiguous run (null otherwise, e.g. a loop that wraps from the last slide to the first).
 */
export function visibleRange(layout: Layout, pos: number): [number, number] | null {
  if (!layout.ready) return null;
  const tx = snapX(layout, pos);
  const shown: { i: number; at: number }[] = [];
  for (let i = 0; i < layout.count; i++) {
    const at = slideOffset(layout, i, tx);
    if (at >= -0.5 && at + layout.slideW <= layout.width + 0.5) shown.push({ i, at });
  }
  shown.sort((a, b) => a.at - b.at);
  const first = shown[0]?.i;
  if (first === undefined) return null;
  return shown.every((s, k) => s.i === first + k) ? [first, first + shown.length - 1] : null;
}

/** The slide closest to the start / centre line at position `pos`. */
export function currentSlide(layout: Layout, pos: number) {
  if (!layout.ready) return 0;
  const tx = snapX(layout, pos);
  let current = 0;
  let best = Infinity;
  for (let i = 0; i < layout.count; i++) {
    const d = Math.abs(slideOffset(layout, i, tx) - layout.offset0);
    if (d < best) {
      best = d;
      current = i;
    }
  }
  return current;
}

/** Public index: the snap index, or (loop) the slide index. */
export function toPublic(layout: Layout, pos: number) {
  return layout.loop ? mod(pos, Math.max(1, layout.count)) : clamp(pos, 0, Math.max(0, layout.snaps.length - 1));
}

/* ---------- Icons ---------- */

/** The shared 24px stroke SVG frame of the carousel icons. @internal */
export function Icon({ d, className }: { d: string; className?: string }) {
  return (
    <svg
      aria-hidden
      focusable="false"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      className={cn("size-4", className)}
    >
      <path d={d} />
    </svg>
  );
}

/** The previous arrow icon. @internal */
export const LeftIcon = () => <Icon d="M14.5 6 8.5 12l6 6" />;
/** The next arrow icon. @internal */
export const RightIcon = () => <Icon d="m9.5 6 6 6-6 6" />;
/** The pause icon of the autoplay control. @internal */
export const PauseIcon = () => <Icon d="M9 6.5v11M15 6.5v11" />;
/** The play icon of the autoplay control. @internal */
export const PlayIcon = () => (
  // The triangle points "forward": mirrored in RTL.
  <svg aria-hidden focusable="false" viewBox="0 0 24 24" className="size-4 rtl:-scale-x-100" fill="currentColor">
    <path d="M8.5 6.2v11.6a.8.8 0 0 0 1.2.7l9.2-5.8a.8.8 0 0 0 0-1.4L9.7 5.5a.8.8 0 0 0-1.2.7Z" />
  </svg>
);

/* ---------- Carousel ---------- */

"use client";

import { type KeyboardEvent } from "react";
import { motion, type MotionValue } from "motion/react";

import { cn } from "../../lib/cn";
import { spring } from "../../motion/tokens";
import { Button } from "../../button/button";
import { LeftIcon, RightIcon } from "./model";

/* ---------- Controls ---------- */

/** The previous or next arrow button. @internal */
export function ArrowButton({
  side,
  overlay,
  rtl,
  disabled,
  onClick,
  onKeyDown,
  label,
}: {
  side: "prev" | "next";
  overlay?: boolean;
  rtl: boolean;
  disabled: boolean;
  onClick: () => void;
  onKeyDown?: (event: KeyboardEvent<HTMLElement>) => void;
  label: string;
}) {
  // "Previous" points towards the start edge: left in LTR, right in RTL.
  const pointsLeft = (side === "prev") !== rtl;
  const button = (
    <Button
      variant="glass"
      size="icon"
      aria-label={label}
      // aria-disabled (not disabled) so focus never drops to <body> at the ends.
      aria-disabled={disabled || undefined}
      onClick={() => !disabled && onClick()}
      onKeyDown={onKeyDown}
      className={cn(
        "rounded-sheen-full aria-disabled:cursor-not-allowed aria-disabled:opacity-40",
        !overlay && "size-9",
        // Over slide art: a page-coloured veil under the icon keeps it legible on any image,
        // and the focus outline gets a page-coloured halo on both sides (two-tone ring).
        overlay && "focus-visible:shadow-[var(--sheen-glass-rim),0_0_0_6px_var(--sheen-bg)]",
      )}
    >
      {overlay && (
        <span
          aria-hidden
          className="pointer-events-none absolute inset-0 -z-10 rounded-[inherit] bg-sheen-bg/55 forced-colors:hidden"
        />
      )}
      {pointsLeft ? <LeftIcon /> : <RightIcon />}
    </Button>
  );
  if (!overlay) return button;
  // Centred by a plain wrapper, so the button's own hover lift (translate) can't fight it.
  return (
    <div
      className={cn(
        "pointer-events-none absolute inset-y-0 z-10 flex items-center [&>*]:pointer-events-auto",
        side === "prev" ? "start-3" : "end-3",
      )}
    >
      {button}
    </div>
  );
}

/** The pagination dots, one per snap position. @internal */
export function Dots({
  count,
  active,
  onSelect,
  progress,
  showProgress,
  coarse,
  reduced,
  rtl,
  names,
  label,
}: {
  count: number;
  active: number;
  onSelect: (i: number) => void;
  progress: MotionValue<number>;
  showProgress: boolean;
  coarse: boolean;
  reduced: boolean;
  rtl: boolean;
  names: string[];
  label: string;
}) {
  const size = coarse ? 44 : 24;
  return (
    <div role="group" aria-label={label} className="relative flex items-center">
      {Array.from({ length: count }, (_, i) => (
        <button
          key={i}
          type="button"
          data-carousel-dot=""
          aria-label={names[i]}
          aria-current={i === active ? "true" : undefined}
          // Roving: only the active dot is in the tab order; arrow keys move between positions.
          tabIndex={i === active ? 0 : -1}
          onClick={() => onSelect(i)}
          style={{ width: size, height: size }}
          className={cn(
            "group/dot relative grid shrink-0 place-items-center rounded-sheen-full",
            "focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-sheen-focus",
            "touch-manipulation [-webkit-tap-highlight-color:transparent]",
          )}
        >
          <span
            aria-hidden
            className={cn(
              // control-border: >= 3:1 against the page and glass in both themes (WCAG 1.4.11).
              "size-2 rounded-full bg-sheen-control-border group-hover/dot:bg-sheen-fg-muted",
              "motion-ok:transition-colors motion-ok:duration-(--sheen-duration-fast) motion-ok:ease-sheen-out",
              i === active && "bg-transparent group-hover/dot:bg-transparent",
              "forced-colors:bg-[GrayText]",
            )}
          />
        </button>
      ))}
      {/*
        The active pill slides between dots (transform) and fills up while autoplay counts down.
        Its accent outline keeps it >= 3:1 even while it is still empty.
      */}
      <motion.span
        aria-hidden
        initial={false}
        animate={{ x: (rtl ? -1 : 1) * (active * size + size / 2 - 12) }}
        transition={reduced ? { duration: 0 } : spring.snappy}
        className="pointer-events-none absolute start-0 top-1/2 h-2 w-6 -translate-y-1/2 overflow-hidden rounded-full bg-sheen-accent-soft shadow-[inset_0_0_0_1.5px_var(--sheen-accent)] forced-colors:bg-[Highlight]"
      >
        <motion.span
          className="sheen-fill absolute inset-0 rounded-full [background-image:var(--sheen-accent-fill)]"
          style={{ scaleX: showProgress ? progress : 1, originX: rtl ? 1 : 0 }}
        />
      </motion.span>
    </div>
  );
}

